/* avatar.js: código compartilhado do avatar (usado por avatar, perfil e comunidade).
   O avatar fica salvo no localStorage em 'trilha-avatar' como {body:'corpo1', skin:0..2}.
   Camadas (de baixo para cima): tatuagem, botas, calça, cintura (cinto/saia, fica por cima da calça), camisa, camiseta (fica por cima da camisa), capa (por cima das roupas; se a peça tiver behind:true em CLOTHES, ela é desenhada ATRÁS do corpo; o jogador pode inverter calça/camisa: campo over), braceletes, maquiagem, boca, olhos, cabelo. Veja SLOTS.
   Uso:  Avatar.ready(()=>{ Avatar.paintFace(elemento) })  // preenche um círculo com o rosto do avatar */
(function(){
const KEY='trilha-avatar';
const SKIN=['#835237','#f9b786','#f6e6de','#454450','#8d909c'],SKIN_N=['pele','pele','pele','golaiafi 1','golaiafi 2']; // 3 e 4 são cores especiais
const SKIN_SPECIAL=[3,4];
// Corpos em tons de cinza (preenchimento claro, contorno escuro). A cor da pele multiplica a imagem.
// face: recorte quadrado (em pixels da imagem) com cabeça e ombros, usado nos círculos pequenos.
const BODIES=[
 {id:'corpo1',n:'Corpo 1',face:{x:95,y:0,s:440},src:'data:image/png;base64,'},
 {id:'corpo2',n:'Corpo 2',face:{x:80,y:0,s:340},src:'data:image/png;base64,'}
];
// Roupas: um PNG por corpo (mesma peça, formato diferente). x,y = posição no corpo, em pixels da imagem do corpo.
// Para adicionar outra peça, crie outra entrada em CLOTHES (ex.: calca) e uma opção na aba correspondente do avatar.html.
const CLOTHES={
 camisa:{n:'Camisa',slot:'shirt',por_corpo:{
  corpo1:{x:41,y:244,src:'data:image/png;base64,'},
  corpo2:{x:59,y:200,src:'data:image/png;base64,'}}},
 calca:{n:'Calça',slot:'pants',por_corpo:{
  corpo1:{x:144,y:566,src:'data:image/png;base64,'},
  corpo2:{x:85,y:472,src:'data:image/png;base64,'}}},
 cabelo1:{n:'Cabelo 1',slot:'hair',por_corpo:{
  corpo1:{x:129,y:-98,src:'data:image/png;base64,'},
  corpo2:{x:89,y:-85,src:'data:image/png;base64,'}}},
 cabelo2:{n:'Cabelo 2',slot:'hair',por_corpo:{
  corpo1:{x:111,y:-97,src:'data:image/png;base64,'},
  corpo2:{x:64,y:-114,src:'data:image/png;base64,'}}},
 // ---- Kairon: corpo1 (masculino) e corpo2 (feminino). ----
 // slot: hair|shirt|tshirt|cape|bracelets|pants|belt|boots|eyes|mouth|makeup|tattoo. O preço e a categoria na loja ficam no CATALOG do loja.js (campo piece = chave daqui).
 kairon_boca:{n:'Boca do Kairon',slot:'mouth',por_corpo:{
  corpo1:{x:276,y:182,src:'data:image/png;base64,'},
  corpo2:{x:203,y:143,src:'data:image/png;base64,'}}},
 kairon_olhos:{n:'Olhos do Kairon',slot:'eyes',por_corpo:{
  corpo1:{x:214,y:96,src:'data:image/png;base64,'},
  corpo2:{x:160,y:62,src:'data:image/png;base64,'}}},
 kairon_braceletes:{n:'Braceletes do Kairon',slot:'bracelets',por_corpo:{
  corpo1:{x:10,y:436,src:'data:image/png;base64,'},
  corpo2:{x:14,y:343,src:'data:image/png;base64,'}}},
 kairon_botas:{n:'Botas do Kairon',slot:'boots',por_corpo:{
  corpo1:{x:140,y:913,src:'data:image/png;base64,'},
  corpo2:{x:72,y:923,src:'data:image/png;base64,'}}},
 kairon_cabelo:{n:'Cabelo do Kairon',slot:'hair',por_corpo:{
  corpo1:{x:98,y:-84,src:'data:image/png;base64,'},
  corpo2:{x:32,y:-92,src:'data:image/png;base64,'}}},
 kairon_saia:{n:'Saia do Kairon',slot:'belt',por_corpo:{
  corpo1:{x:60,y:544,src:'data:image/png;base64,'},
  corpo2:{x:51,y:435,src:'data:image/png;base64,'}}},
 kairon_tatuagens:{n:'Tatuagens do Kairon',slot:'tattoo',por_corpo:{
  corpo1:{x:16,y:94,src:'data:image/png;base64,'},
  corpo2:{x:13,y:46,src:'data:image/png;base64,'}}},
 kairon_camisa2:{n:'Camiseta do Kairon',slot:'tshirt',por_corpo:{
  corpo1:{x:165,y:255,src:'data:image/png;base64,'},
  corpo2:{x:150,y:210,src:'data:image/png;base64,'}}}
};
const STAR=(x,y)=>'<path transform="translate('+x+' '+y+')" d="M0-16Q2-3 16 0Q2 3 0 16Q-2 3-16 0Q-2-3 0-16Z" fill="#8f8f95"/>';
const cache={},cv={};
function tinted(b,i){
  const k=b.id+i;if(cache[k])return cache[k];
  const w=b.img.naturalWidth,h=b.img.naturalHeight,c=document.createElement('canvas');c.width=w;c.height=h;
  const x=c.getContext('2d');x.drawImage(b.img,0,0);
  const d=x.getImageData(0,0,w,h),p=d.data,hx=SKIN[i];
  const r=parseInt(hx.slice(1,3),16),g=parseInt(hx.slice(3,5),16),bl=parseInt(hx.slice(5,7),16);
  for(let n=0;n<p.length;n+=4){const m=p[n]/255;p[n]=r*m;p[n+1]=g*m;p[n+2]=bl*m}
  x.putImageData(d,0,0);cv[k]=c;
  return cache[k]=c.toDataURL('image/png');
}
// peça de roupa do avatar (ou '' se não tiver): imagem da peça para o corpo escolhido, na escala do corpo
// peças vestidas, de baixo para cima: [{x,y,src,img}, ...]. [tipo da peça (slot em CLOTHES), campo salvo no avatar] (os dois nomes são iguais)
const SLOTS=[['tattoo','tattoo'],['boots','boots'],['pants','pants'],['belt','belt'],['shirt','shirt'],['tshirt','tshirt'],['bracelets','bracelets'],['cape','cape'],['makeup','makeup'],['mouth','mouth'],['eyes','eyes'],['hair','hair']];
const FACE_SLOTS=['makeup','mouth','eyes','hair']; // peças do rosto/cabeça: a pré-visualização mostra só o rosto
// a.over: 'shirt' (padrão: camisa por cima da calça) ou 'pants' (calça por cima da camisa)
function layers(a){const l=SLOTS.slice();if(a.over==='pants'){ // calça (e cintura) por cima da camisa (e camiseta): move o grupo calça+cintura para depois de camisa+camiseta
  const g=l.filter(x=>x[0]==='pants'||x[0]==='belt'),r=l.filter(x=>x[0]!=='pants'&&x[0]!=='belt'),i=r.findIndex(x=>x[0]==='tshirt');r.splice(i+1,0,...g);return r}return l}
// back=true: só as peças desenhadas atrás do corpo (capa com behind:true); back=false: as da frente
function pieces(a,b,back){const o=[];layers(a).forEach(([slot,key])=>{const c=a[key]&&CLOTHES[a[key]];if(c&&c.slot===slot&&c.por_corpo[b.id]&&!!c.behind===!!back)o.push(c.por_corpo[b.id])});return o}
function clothesSVG(a,b,ox,oy,s,back){return pieces(a,b,back).map(p=>'<image href="'+p.src+'" x="'+(ox+p.x*s)+'" y="'+(oy+p.y*s)+'" width="'+(p.img.naturalWidth*s)+'" height="'+(p.img.naturalHeight*s)+'"/>').join('')}
function svg(a){
  const b=BODIES.find(x=>x.id===a.body),FH=400,FW=Math.round(FH*b.img.naturalWidth/b.img.naturalHeight),FX=Math.round((400-FW)/2);
  return '<svg viewBox="0 0 400 500" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Seu avatar"><circle cx="200" cy="240" r="170" fill="#b6b6ba"/>'+STAR(52,200)+STAR(348,200)
   +'<ellipse cx="200" cy="454" rx="84" ry="8" fill="rgba(0,0,0,.25)"/>'+clothesSVG(a,b,FX,50,FH/b.img.naturalHeight,true)+'<image href="'+tinted(b,a.skin)+'" x="'+FX+'" y="50" width="'+FW+'" height="'+FH+'"/>'+clothesSVG(a,b,FX,50,FH/b.img.naturalHeight,false)+'</svg>';
}
const fcache={};
function faceURL(a){
  const k=a.body+'|'+a.skin+'|'+(a.over||'')+'|'+SLOTS.map(([,key])=>a[key]||'').join('|');if(fcache[k])return fcache[k];
  const b=BODIES.find(x=>x.id===a.body),f=b.face,c=document.createElement('canvas');c.width=c.height=160;
  const x=c.getContext('2d');x.fillStyle='#b6b6ba';x.fillRect(0,0,160,160);
  tinted(b,a.skin);const q=160/f.s,ps=pieces(a,b,false),bk=pieces(a,b,true);
  // o cabelo costuma passar do topo da cabeça: sobe o recorte o bastante para não cortá-lo
  const fy=Math.min(f.y,ps.reduce((m,p)=>Math.min(m,p.y-4),f.y));
  bk.forEach(p=>x.drawImage(p.img,(p.x-f.x)*q,(p.y-fy)*q,p.img.naturalWidth*q,p.img.naturalHeight*q));
  x.drawImage(cv[b.id+a.skin],(0-f.x)*q,(0-fy)*q,b.img.naturalWidth*q,b.img.naturalHeight*q);
  ps.forEach(p=>x.drawImage(p.img,(p.x-f.x)*q,(p.y-fy)*q,p.img.naturalWidth*q,p.img.naturalHeight*q));
  return fcache[k]=c.toDataURL('image/png');
}
// lê o avatar salvo; devolve null se o jogador ainda não escolheu nenhum
// cores bloqueadas só valem se foram compradas na loja ('trilha-loja')
const SKIN_LOCKED=[4]; // cores que precisam ser compradas na loja. A GOLAIAFI 1 (3) é grátis; a GOLAIAFI 2 (4) custa 150 diamantes (preço no CATALOG do loja.js)
function owns(skin){
  if(!SKIN_LOCKED.includes(skin))return true;
  try{const o=JSON.parse(localStorage.getItem('trilha-loja'));return !!(o&&Array.isArray(o.owned)&&o.owned.includes('pele:'+skin))}catch(e){return false}
}
// peça paga? Só vale se foi comprada na loja. Sem loja.js na página (ou peça fora do catálogo), a peça conta como liberada.
function shopItem(key){const L=window.Loja;return L?(L.CATALOG.find(x=>x.piece===key||x.hair===key)||null):null}
function ownsPiece(key){const it=shopItem(key);return it?window.Loja.owned(it.id):true}
function saved(){
  try{const v=JSON.parse(localStorage.getItem(KEY));
    if(v&&BODIES.some(b=>b.id===v.body)&&v.skin>=0&&v.skin<SKIN.length){
      if(v.shirt==='kairon_camisa'&&!v.bracelets){v.bracelets='kairon_braceletes';v.shirt=null} // antiga "camisa do Kairon"
      if(v.shirt==='kairon_camisa2'&&!v.tshirt){v.tshirt='kairon_camisa2';v.shirt=null} // a camisa do Kairon virou camiseta
      if(v.pants==='kairon_saia'&&!v.belt){v.belt='kairon_saia';v.pants=null} // a saia do Kairon virou cintura
      const o={body:v.body,skin:owns(v.skin)?v.skin:1,over:v.over==='pants'?'pants':'shirt'};
      SLOTS.forEach(([slot,key])=>{const id=v[key],c=id&&CLOTHES[id];o[key]=(c&&c.slot===slot&&ownsPiece(id))?id:null});
      return o}}catch(e){}
  return null;
}
const PIECES=[];Object.values(CLOTHES).forEach(c=>Object.values(c.por_corpo).forEach(p=>PIECES.push(p)));
let ready=0,cbs=[];
function ready_(fn){ready===BODIES.length+PIECES.length?fn():cbs.push(fn)}
[...BODIES,...PIECES].forEach(b=>{b.img=new Image();b.img.onload=()=>{if(++ready===BODIES.length+PIECES.length){cbs.forEach(f=>f());cbs=[]}};b.img.src=b.src});
// recorte quadrado (x0,y0,s em pixels do corpo) do avatar a, com as peças que ele veste
function renderCrop(a,b,x0,y0,s,px){
  const c=document.createElement('canvas');c.width=c.height=px;
  const x=c.getContext('2d');x.fillStyle='#b6b6ba';x.fillRect(0,0,px,px);
  tinted(b,a.skin);const q=px/s;
  pieces(a,b,true).forEach(p=>x.drawImage(p.img,(p.x-x0)*q,(p.y-y0)*q,p.img.naturalWidth*q,p.img.naturalHeight*q));
  x.drawImage(cv[b.id+a.skin],(0-x0)*q,(0-y0)*q,b.img.naturalWidth*q,b.img.naturalHeight*q);
  pieces(a,b,false).forEach(p=>x.drawImage(p.img,(p.x-x0)*q,(p.y-y0)*q,p.img.naturalWidth*q,p.img.naturalHeight*q));
  return c.toDataURL('image/png');
}
// pré-visualização de UMA peça no avatar do jogador (só a peça, sem as outras roupas).
// Peças do rosto/cabelo: recorte do rosto. Outras (camisa, calça, botas, tatuagem): recorte quadrado em volta da peça.
// Se a peça não existe para o corpo do jogador, usa o primeiro corpo que tiver.
const pcache={};
function previewURL(a,key){
  const c=CLOTHES[key];if(!c)return faceURL(a);
  const b=BODIES.find(x=>x.id===a.body&&c.por_corpo[x.id])||BODIES.find(x=>c.por_corpo[x.id]);
  const k=b.id+'|'+a.skin+'|'+key;if(pcache[k])return pcache[k];
  const aa={body:b.id,skin:a.skin};aa[c.slot]=key;
  if(FACE_SLOTS.includes(c.slot))return pcache[k]=faceURL(aa);
  const p=c.por_corpo[b.id],w=p.img.naturalWidth,h=p.img.naturalHeight,tat=c.slot==='tattoo'; // tatuagem: aproxima do tronco e dos braços, onde ela aparece mais
  const s=tat?w*1.1:Math.max(w,h,300)*1.25,cy=p.y+h*(tat?0.3:0.5);
  return pcache[k]=renderCrop(aa,b,p.x+w/2-s/2,cy-s/2,s,256);
}
// Pinta o rosto do avatar salvo dentro de um círculo (.av). Sem avatar salvo, mantém a inicial do nome.
function paintFace(el){
  const a=saved();if(!a)return false;
  el.textContent='';el.style.backgroundImage='url('+faceURL(a)+')';el.style.backgroundSize='cover';el.style.backgroundPosition='center';
  el.setAttribute('aria-label','Seu avatar');return true;
}
window.Avatar={CLOTHES,KEY,SKIN,SKIN_N,SKIN_SPECIAL,SLOTS,FACE_SLOTS,owns,ownsPiece,shopItem,BODIES,tinted,svg,faceURL,previewURL,saved,ready:ready_,paintFace};
})();
